from rules import amount


def solve(data):
    events = data.get('events', [])
    cutoff = data.get('cutoff', 10**9)

    # Apply the cutoff before resolving revisions. Keep each event's original
    # position for anonymous IDs and for resolving ties.
    selected = {}
    for position, event in enumerate(events):
        if event.get('sequence', 0) > cutoff:
            continue
        event_id = event.get('id', f'anonymous:{position}')
        revision = event.get('revision', 0)
        previous = selected.get(event_id)
        if previous is None or (revision, position) >= (previous[0], previous[1]):
            selected[event_id] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in selected.values():
        if event.get('void', False):
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances[key] = balances.get(key, 0) + amount(event, data.get('rounding', 'half_up'))

    return {'balances': balances}

def _rounded_ratio(numerator, denominator, mode):
    if mode == 'floor':
        return numerator // denominator
    # half_up for nonnegative values: exact halves round upward.
    return (2 * numerator + denominator) // (2 * denominator)


def amount(event, mode):
    price_quantity = event['price'] * event.get('quantity', 1)
    discount_bp = max(0, min(10000, event.get('discount_bp', 0)))
    net = _rounded_ratio(price_quantity * (10000 - discount_bp), 10000, mode)

    tax_bp = event.get('tax_bp', 0)
    tax = _rounded_ratio(net * tax_bp, 10000, mode)
    total = net + tax
    if event.get('kind') == 'refund':
        return -total
    return total
